using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
class SoundModeControl : Control {
    internal int Index=1;internal event EventHandler SelectionChanged;static readonly string[] labels={"끔","이어폰","전체"};
    internal SoundModeControl(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.Selectable,true);TabStop=true;AccessibleRole=AccessibleRole.Slider;AccessibleName="효과음 출력 모드";Cursor=Cursors.Hand;}
    internal void SetIndex(int index){Index=Math.Max(0,Math.Min(2,index));AccessibleDescription=labels[Index];Invalidate();}
    void Select(int index){SetIndex(index);if(SelectionChanged!=null)SelectionChanged(this,EventArgs.Empty);}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left){Focus();Select(e.X*3/Math.Max(1,Width));}}
    protected override bool IsInputKey(Keys keyData){var key=keyData&Keys.KeyCode;return key==Keys.Left||key==Keys.Right||key==Keys.Up||key==Keys.Down||key==Keys.Home||key==Keys.End||key==Keys.PageUp||key==Keys.PageDown||base.IsInputKey(keyData);}
    protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Left||e.KeyCode==Keys.Right){Select(Index+(e.KeyCode==Keys.Left?-1:1));e.Handled=true;}else if(e.KeyCode==Keys.Home||e.KeyCode==Keys.End){Select(e.KeyCode==Keys.Home?0:2);e.Handled=true;}else base.OnKeyDown(e);}
    protected override void OnPaint(PaintEventArgs e){PetTheme.PaintUnder(e.Graphics,this);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;using(var shape=SettingArt.Round(new Rectangle(0,0,Width-1,Height-1),9))using(var fill=new SolidBrush(PetTheme.Button))g.FillPath(fill,shape);int w=Width/3;using(var shape=SettingArt.Round(new Rectangle(Index*w+2,2,w-4,Height-5),7))using(var fill=new SolidBrush(PetTheme.Accent))g.FillPath(fill,shape);for(int i=0;i<3;i++)using(var ink=new SolidBrush(i==Index?PetTheme.SelectionInk:PetTheme.Ink))using(var format=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center})g.DrawString(labels[i],Font,ink,new Rectangle(i*w,0,w,Height),format);if(Focused&&ShowFocusCues)using(var pen=new Pen(PetTheme.Ink,1))using(var shape=SettingArt.Round(new Rectangle(2,2,Width-5,Height-5),7))g.DrawPath(pen,shape);}
}
